// (order_id, product_id, quantity). Ціна підставиться з каталогу нижче —
// у реальному житті це знімок ціни на момент купівлі.
export const ITEMS: Array<[string, string, number]> = [
  ['1', '1', 1], ['1', '4', 2],
  ['2', '7', 1], ['2', '9', 1], ['2', '4', 3],
  ['3', '8', 1],
  ['4', '2', 1], ['4', '3', 1],
  ['5', '6', 1], ['5', '5', 2],
  ['6', '10', 1], ['6', '9', 2],
  ['7', '4', 5], ['7', '5', 1], ['7', '3', 1],
  ['8', '7', 2], ['8', '1', 1], ['8', '2', 1],
];

async function main(): Promise<void> {
  const ds = await AppDataSource.initialize();

  try {
    await ds.transaction(async (manager) => {
      // Порядок важливий: спершу батьки, потім діти — інакше FK відіб'є вставку.
      await manager.getRepository(User).save(USERS as User[]);
      await manager.getRepository(Product).save(PRODUCTS as Product[]);

      const priceOf = new Map(PRODUCTS.map((p) => [p.id!, p.priceCents!]));

      const items: Array<Partial<OrderItem>> = ITEMS.map(
        ([orderId, productId, quantity], index) => ({
          id: String(index + 1),
          orderId,
          productId,
          quantity,
          unitPriceCents: priceOf.get(productId)!,
        }),
      );

      // Сума замовлення мусить дорівнювати сумі позицій — рахуємо, а не
      // вигадуємо, інакше дані брешуть уже на старті.
      const totals = new Map<string, number>();
      for (const item of items) {
        const sum = item.quantity! * item.unitPriceCents!;
        totals.set(item.orderId!, (totals.get(item.orderId!) ?? 0) + sum);
      }

      const orders = ORDERS.map((order) => ({
        ...order,
        totalCents: totals.get(order.id!) ?? 0,
      }));

      await manager.getRepository(Order).save(orders as Order[]);
      await manager.getRepository(OrderItem).save(items as OrderItem[]);

      // Явні id не рухають послідовність IDENTITY: наступна автоматична
      // вставка спробувала б id = 1 і впала б на дублікаті ключа. Тому
      // після seed синхронізуємо лічильники з максимальним наявним id.
      for (const table of ['users', 'products', 'orders', 'order_items']) {
        await manager.query(
          `SELECT setval(pg_get_serial_sequence($1, 'id'), COALESCE((SELECT max(id) FROM "${table}"), 1))`,
          [table],
        );
      }
    });

    const counts = await ds.query<Array<Record<string, string>>>(`
      SELECT (SELECT count(*) FROM users)       AS users,
             (SELECT count(*) FROM products)    AS products,
             (SELECT count(*) FROM orders)      AS orders,
             (SELECT count(*) FROM order_items) AS order_items
    `);

    console.log('✔ seed виконано (ідемпотентно). Рядків у таблицях:');
    console.table(counts[0]);
  } finally {
    await ds.destroy();
  }
}

// Запускаємо main лише коли файл викликали напряму: демо ДЗ-14 імпортують
// звідси константи (SEED_BALANCE_CENTS, ORDERS) і не мусять перезаливати базу.
if (require.main === module) {
  main().catch((error: unknown) => {
    console.error('\n✖ seed не відпрацював.\n');
    console.error(error instanceof Error ? error.message : String(error));
    process.exit(1);
  });
}
